        // maxChars is used when the tgt field has a maxlength restriction
        maxChars = typeof(maxChars) != 'undefined' ? maxChars : -1;

        $(src).on('focus.textAutoFill', function(evt){
            var val = $(tgt).val();
            tgtEmpty = (val === 'undefined' || val === null || val === '' || ignoreEmpty === true);
            srcFocused = true;
        });

