        ALPHA_NUMERIC: function(txt){if(typeof txt === 'undefined' || txt === null){return txt;} return txt.replace( /[^a-zA-Z0-9]/g, '' );},
        DIGITS_DOT: function(txt){if(typeof txt === 'undefined' || txt === null){return txt;} return txt.replace( /[^0-9\.]/g, '' );},

